from inspect import getcallargs


def _get_bts_id_arg_name(passed_args):
    if 'gnb_id' in passed_args:
        return 'gnb_id'
    elif 'enb_id' in passed_args:
        return 'enb_id'
    elif 'bts_id' in passed_args:
        return 'bts_id'
    else:
        raise ValueError("One of parameter [gnb_id, enb_id, bts_id] is required")


def login_logout(web_fun):
    @wraps(web_fun)
    def wrapper(self, *args, **kwargs):
        refresh_token_threshold = 240
        passed_args = getcallargs(web_fun, self, *args, **kwargs)
        bts_id_arg_name = _get_bts_id_arg_name(passed_args=passed_args.keys())
        passed_args[bts_id_arg_name] = int(passed_args[bts_id_arg_name])
        self._connection_alias = self.rest_alias.format(passed_args[bts_id_arg_name])
        if "asir_connection_alias" in passed_args.keys():
            self._connection_alias += "_{}".format(passed_args["asir_connection_alias"])
        kw_timeout = passed_args.get('timeout')
        if kw_timeout and int(kw_timeout) > 100:
            refresh_token_threshold = 120
        self.connect(bts_id=passed_args[bts_id_arg_name], refresh_token_threshold=refresh_token_threshold)
        result = web_fun(**passed_args)
        return result

    return wrapper


def login_gui_if_needed(web_fun):
    @wraps(web_fun)
    def wrapper(self, *args, **kwargs):
        passed_args = getcallargs(web_fun, self, *args, **kwargs)
        bts_id_arg_name = _get_bts_id_arg_name(passed_args=passed_args.keys())
        passed_args[bts_id_arg_name] = int(passed_args[bts_id_arg_name])
        bts_id = passed_args[bts_id_arg_name]
        gui_alias = self.gui_alias.format(bts_id)

        if gui_alias not in selenium_asir_browser_instances:
            self.login_gui(bts_id=bts_id)
        else:
            logging.debug("[{}] Already logged".format(gui_alias))
            self.gui_asir = selenium_asir_browser_instances[gui_alias]
            logging.debug("[{}] Use instance: {}".format(gui_alias, id(self.gui_asir)))
            # TODO - when automatically logout, need to login again
            #       similar like in generic_bts
            #       or maybe keep last kw call time and if it's more than 5 minutes - login again
            #       postponed for now - GUI used only for SCF migration
        return web_fun(**passed_args)

    return wrapper


all_generic_asir_instances = {}
selenium_asir_browser_instances = {}
access_token_generation_time = {}


class GenericAsirHub(object):
    """ASIR hub keywords for gNB"""

    ROBOT_LIBRARY_SCOPE = 'SUITE'
    ROBOT_LISTENER_API_VERSION = 2

    asir = asir_admin()
    gui_asir = None

    def __init__(self, bts_type='GNB'):
        """
        Constructor of GenericAsirHub class.

        :param bts_type: GNB|ENB
        """
        self.ROBOT_LIBRARY_LISTENER = self

        self.bts_type = bts_type
        self.rest_alias = device_aliases.rest_asir.format(bts_type, '{}')
        self.gui_alias = device_aliases.gui_asir.format(bts_type, '{}')
        self.ssh_bts_hub = device_aliases.ssh_bts_hub.format(bts_type, '{}', '{}')
        self.ssh_ru_alias = device_aliases.ssh_bts_du_ru.format(bts_type, '{}', '{}', '{}')
        self._connection_alias = None
        all_generic_asir_instances[id(self)] = type(self).__name__

    def __del__(self):
        if id(self) in all_generic_asir_instances:
            logging.debug("Destroy instance of {}. ID: {}".format(type(self).__name__, id(self)))
            del all_generic_asir_instances[id(self)]
            if not all_generic_asir_instances:
                logging.debug("It's last GenericAsirHub instance - teardown connections")
                self._close()

    def _close(self):
        """
        Called when robot test execution ends
        """
        self.teardown_all_browsers()
        self._teardown_all_aliases()

    @property
    def connection(self):
        return self.asir.store.get(self._connection_alias)

    def connect(self, bts_id=0, du_id=0, force=False, timeout=90, interval=10, refresh_token_threshold=240):
        """
        Connect to gNB ASIR hub.

        :param bts_id:                      BTS id - related to Test Line configuration
        :param du_id: du id
        :param force:                       True/False - If True - first disconnect if already connected.
        :param timeout:                     Timeout for setup connection.
        :param interval:                    Time interval between next connection attempts
        :param refresh_token_threshold:     if access_token_time > threshold then token will be regenerate.
        :return: None
        """

        if force:
            self.disconnect(bts_id=bts_id)
        if self._connection_alias is None:
            self._connection_alias = self.rest_alias.format(bts_id)

        start_time = time.time()
        if self._connection_alias in access_token_generation_time:
            access_token_time = int(start_time - access_token_generation_time[self._connection_alias])
            logging.debug("Access Token generated {} seconds ago".format(access_token_time))
            if access_token_time > refresh_token_threshold:  # token expires by default in 300 seconds
                if access_token_time > 299:
                    logging.debug("Token expired after 300 seconds - disconnect and request new connection")
                    self.disconnect()
                else:
                    logging.debug("Access Token generated more than {} seconds - REFRESHING TOKEN".
                                  format(refresh_token_threshold))
                    try:
                        self._refresh_token()
                    except AuthenticationFailed as e:
                        logging.debug(f"Refreshing token failed. Details: {e}")
                        logging.info("Disconnect and request new connection")
                        self.disconnect()
        while time.time() < start_time + timeout:
            if self._connection_alias in [item[0] for item in self.asir.store.all]:
                logging.debug("[{}] Already connected - check if connection working".format(self._connection_alias))
                if self._try_to_get_site_info():
                    logging.debug("[{}] Connection is working".format(self._connection_alias))
                    return
                else:
                    logging.debug("[{}] Connection is NOT working.\n"
                                  "Wait {} seconds and set-up connection again".format(self._connection_alias,
                                                                                       interval))
                    time.sleep(interval)
            try:
                self._connect(bts_id=bts_id, du_id=du_id)
                access_token_generation_time[self._connection_alias] = time.time()
            except Exception as err:  # need to figure out better exception
                logging.debug("Caught exception during connection to [{}]: {}".format(self._connection_alias, err))
                logging.debug("Wait {} seconds and set-up connection again".format(interval))
                time.sleep(interval)
        else:
            raise AsirConnection("set-up connection time-outed in {} sec".format(timeout))

    def _connect(self, bts_id=0, du_id=0):
        credentials = tl_config.get_web_credentials_for_du(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        logging.debug("[ASIR] Connecting to {}  {}".format(self._connection_alias, credentials['ip']))
        self.asir.connect_to(host=credentials['ip'],
                             port=3601,
                             username=credentials['username'],
                             password=credentials['password'],
                             asir_version="ASIR_22R3",
                             secure=False,
                             alias=self._connection_alias)

    def disconnect(self, bts_id=0):
        """
        Disconnect from gNB ASIR hub.

        :param bts_id:          BTS id - related to Test Line configuration
        :return: None
        """
        try:
            logging.debug("[ASIR] Disconnecting from {}".format(self._connection_alias))
            self.asir.disconnect(connection=self._connection_alias)
        except AliasLookupError:
            logging.debug("[ASIR] Already disconnected")
        except urllib3.exceptions.MaxRetryError:
            logging.debug("[ASIR] Max retries exceeded - it means that most probably connection already disconnected")
        finally:
            if self._connection_alias in access_token_generation_time:
                del access_token_generation_time[self._connection_alias]

    def _teardown_all_aliases(self):
        """
        Called when robot test execution ends
        """
        for item in list(self.asir.store.all):
            self._connection_alias = item[0]
            self.disconnect()

    def _refresh_token(self):
        self.asir.refresh_token(connection=self._connection_alias)
        access_token_generation_time[self._connection_alias] = time.time()

    def _try_to_get_site_info(self):
        try:
            number_logged_users = self.asir.get_number_of_logged_in_users(connection=self._connection_alias)
            logging.debug("[{}] Number of logged users: {}".format(self._connection_alias, number_logged_users))
            site_info = self.asir.get_site_info(connection=self._connection_alias)
            logging.debug("[{}] Site Info: {}".format(self._connection_alias, site_info))
        except ApiException as err:
            logging.debug("Cannot get site info. Details\n{}".format(err))
            if err.reason == 'Unauthorized' and 'invalid_token' in err.body:
                logging.debug("Connection is Unauthorized - disconnecting")
                self.disconnect()
                return False
            if err.reason == 'Service Unavailable':
                logging.info("ASIR WebEM is Unavailable")
                self.disconnect()
                return False
        except urllib3.exceptions.MaxRetryError:
            logging.debug("Max retries exceeded - wait when connection will be available")
            self.disconnect()
            return False
        return True

    def login_gui(self, bts_id=0, log_dir=None, interface='mplane', force=False):
        """
        Login to BTS via GUI

        :param bts_id:      enb_id or gnb_id, related to test line configuration, default set to 0
        :param log_dir:     Directory for GUI logs
        :param interface:   connect via 'mplane' or 'lmp'
        :param force:      True/False - If True - first disconnect if already connected.
        :return: None
        """

        self.gui_asir = selenium_asir()
        logging.debug("[{}] Created new instance: {}".format(self.gui_alias.format(bts_id), id(self.gui_asir)))

        if selenium_asir_browser_instances:
            self.gui_asir._display = list(selenium_asir_browser_instances.values())[0]._display
        else:
            logging.debug("Enable Virtual Display")
            self.gui_asir.enable_virtual_display()

        selenium_asir_browser_instances[self.gui_alias.format(bts_id)] = self.gui_asir

        if force:
            self.logout_gui(bts_id=bts_id)
        self._login_gui(bts_id, interface=interface, log_dir=log_dir)

    def _login_gui(self, bts_id=0, du_id=0, interface='mplane', timeout=120, log_dir=None):
        gui_alias = self.gui_alias.format(bts_id)
        logging.debug("[{}] New GUI connection".format(gui_alias))
        credentials = tl_config.get_web_credentials_for_du(bts_id, du_id, self.bts_type)
        if log_dir is None:
            log_dir = os.path.join(get_log_path(), 'selenium_logs', gui_alias)
        download_folder = os.path.join(log_dir, "download")
        if not os.path.exists(download_folder):
            os.makedirs(download_folder)

        if interface.lower() == 'lmp':
            credentials['ip'] = self._get_lmp_ip_address(bts_id=bts_id, du_id=du_id)

        self.gui_asir.login(url='https://{}:3601/'.format(credentials['ip']),
                            username=credentials['username'],
                            password=credentials['password'],
                            screenshot_dir=os.path.join(log_dir, 'screenshot'),
                            download_dir=download_folder,
                            alias=gui_alias,
                            timeout=timeout)

    def logout_gui(self, bts_id=0):
        """
        Logout from BTS via GUI

        :return: None
        """

        try:
            self.gui_asir.logout(sc=self.gui_alias.format(bts_id))
        except Exception:
            logging.debug("Logout failed - most probably already logout")
        self.teardown_browser(bts_id)

    def teardown_browser(self, bts_id=0):
        gui_alias = self.gui_alias.format(bts_id)
        logging.debug("[{}] Close Browser".format(gui_alias))
        self.gui_asir.close_browser(sc=gui_alias)
        del selenium_asir_browser_instances[gui_alias]

    def teardown_all_browsers(self):
        for gui_alias, gui_coam in selenium_asir_browser_instances.copy().items():
            if gui_alias in selenium_asir_browser_instances:
                logging.debug("[{}] Close Browser".format(gui_alias))
                gui_coam.close_browser(sc=gui_alias)
                del selenium_asir_browser_instances[gui_alias]

    def _get_lmp_ip_address(self, bts_id=0, du_id=0):
        lmp_credentials = tl_config.get_du_lmp_credentials(bts_id=bts_id, du_id=du_id, bts_type=self.bts_type)
        lmp_address = lmp_credentials['host'] if lmp_credentials['host'] else '192.168.255.129'
        return lmp_address
